import{_ as e,o,c as s,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Сессии","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/sessions.md","filePath":"ru/guides/sessions.md","lastUpdated":1792323081000}'),i={name:"ru/guides/sessions.md"};function r(l,t,d,n,c,h){return o(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="сессии" tabindex="-1">Сессии <a class="header-anchor" href="#сессии" aria-label="Permalink to &quot;Сессии&quot;">​</a></h1><p><strong>Сессия</strong> — это независимая ветка диалога между пользователем и Bot. Каждая сессия ведёт собственное контекстное окно и историю сообщений, позволяя Bot сосредоточиться на конкретной теме или задаче без помех от других разговоров.</p><hr><h2 id="концепция-изоляция-диалогов" tabindex="-1">Концепция: изоляция диалогов <a class="header-anchor" href="#концепция-изоляция-диалогов" aria-label="Permalink to &quot;Концепция: изоляция диалогов&quot;">​</a></h2><p>Когда вы общаетесь с Bot, ваши сообщения группируются в сессию. Bot использует историю сессии, чтобы удерживать контекст. Новая сессия сбрасывает этот контекст: вы получаете свежий диалог, не теряя предыдущий.</p><p>Сессии привязаны к конкретному Bot — каждый Bot управляет своим набором сессий независимо.</p><hr><h2 id="типы-сессии" tabindex="-1">Типы сессий <a class="header-anchor" href="#типы-сессии" aria-label="Permalink to &quot;Типы сессий&quot;">​</a></h2><p>Memoh использует пять типов сессий, чтобы разделять разные виды активности Bot:</p><table tabindex="0"><thead><tr><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>Обычные диалоги, начатые пользователем. Тип сессии по умолчанию при общении с Bot.</td></tr><tr><td><strong>Discuss</strong></td><td>Режим наблюдения. Bot по умолчанию может молчать и говорит, только когда решает отправить в разговор настоящий ответ.</td></tr><tr><td><strong>Schedule</strong></td><td>Создаётся при срабатывании задачи по расписанию. Содержит запись того, как Bot выполняет команду, запущенную по cron.</td></tr><tr><td><strong>Subagent</strong></td><td>Создаётся, когда Bot делегирует задачу субагенту. Содержит независимый рабочий контекст субагента.</td></tr><tr><td><strong>ACP Agent</strong></td><td>Создаётся, когда из чат-пространства используется включённый ACP-совместимый агент для программирования.</td></tr></tbody></table><p>Только сессии <strong>Chat</strong> и <strong>Discuss</strong> создаются напрямую из обычных пользовательских маршрутов диалога, таких как <code>/new chat</code> и <code>/new discuss</code>. Сессии <strong>ACP Agent</strong> создаёт и ведёт рабочий процесс Agents/ACP, а остальные типы сессий управляются системой и выглядят в списке сессий как записи только для чтения.</p><h3 id="chat-и-discuss" tabindex="-1">Chat и Discuss <a class="header-anchor" href="#chat-и-discuss" aria-label="Permalink to &quot;Chat и Discuss&quot;">​</a></h3><p><code>chat</code> и <code>discuss</code> — два типа сессий, которые вы чаще всего увидите в обычных ветках диалога.</p><p><strong>Chat</strong> означает:</p><ul><li>разговор ведёт себя как обычный обмен с ассистентом</li><li>отправив запрос, пользователь ожидает видимый ответ</li><li>это режим по умолчанию в приложении и в диалогах формата личных сообщений</li></ul><p><strong>Discuss</strong> означает:</p><ul><li>Bot наблюдает за идущим разговором, часто в группе</li><li>прямой текстовый вывод модели считается внутренним монологом</li><li>Bot обращается к разговору, только когда явно выполняет действие <code>send</code></li><li>молчание — допустимый и часто желательный выбор</li></ul><p>На практике именно <code>discuss</code> делает Memoh не синхронным чат-ботом, а участником, который сам решает, вступать ли в разговор.</p><hr><h2 id="новая-сессия-командои-new" tabindex="-1">Новая сессия командой <code>/new</code> <a class="header-anchor" href="#новая-сессия-командои-new" aria-label="Permalink to &quot;Новая сессия командой `/new`&quot;">​</a></h2><p>Слэш-команда <code>/new</code> создаёт свежую сессию на текущем маршруте диалога, сбрасывая активный контекст без удаления старой истории.</p><p>Поддерживаемые формы:</p><ul><li><code>/new</code> — создать новую сессию с типом по умолчанию для текущего контекста</li><li><code>/new chat</code> — принудительно создать обычную сессию chat</li><li><code>/new discuss</code> — принудительно создать сессию discuss</li></ul><p>Сессии ACP Agent через <code>/new</code> не создаются. Они запускаются из чат-пространства после того, как на Bot включён ACP-совместимый агент.</p><p>Маршрутизация по умолчанию:</p><ul><li><strong>встроенный чат приложения</strong> по умолчанию использует <code>chat</code></li><li><strong>личные диалоги</strong> по умолчанию используют <code>chat</code></li><li><strong>групповые диалоги на адаптерах каналов</strong> по умолчанию используют <code>discuss</code></li></ul><p><code>/new discuss</code> не поддерживается во встроенном чат-канале приложения. Если нужно явно создавать сессии discuss, используйте настоящий адаптер канала, например Telegram или Discord.</p><p>Это работает во всех поддерживаемых каналах:</p><h3 id="во-внешних-каналах-telegram-discord-feishu-и-других" tabindex="-1">Во внешних каналах (Telegram, Discord, Feishu и других) <a class="header-anchor" href="#во-внешних-каналах-telegram-discord-feishu-и-других" aria-label="Permalink to &quot;Во внешних каналах (Telegram, Discord, Feishu и других)&quot;">​</a></h3><p>Отправьте <code>/new</code>, <code>/new chat</code> или <code>/new discuss</code> сообщением Bot. Он:</p><ol><li>Создаст новую сессию запрошенного или выведенного типа.</li><li>Направит все ваши последующие сообщения в эту новую сессию.</li><li>История предыдущей сессии сохранится, но перестанет быть активной.</li></ol><p>Это особенно полезно, когда:</p><ul><li>вы хотите сменить тему, чтобы Bot не ссылался на старый контекст;</li><li>разговор стал слишком длинным и хочется чистого старта;</li><li>вы переключаетесь между разными задачами.</li></ul><h3 id="в-приложении" tabindex="-1">В приложении <a class="header-anchor" href="#в-приложении" aria-label="Permalink to &quot;В приложении&quot;">​</a></h3><p>В приложении есть боковая панель сессий, где можно:</p><ul><li>Нажать кнопку <strong>New Session</strong>, чтобы создать свежую сессию chat.</li><li>Переключаться между существующими сессиями, щёлкая по ним.</li><li>Искать сессии по содержимому.</li><li>Фильтровать сессии по типу (<code>chat</code>, <code>discuss</code>, <code>schedule</code>, <code>subagent</code>, <code>acp_agent</code>).</li><li>Переименовывать и удалять сессии.</li></ul><hr><h2 id="управление-сессиями" tabindex="-1">Управление сессиями <a class="header-anchor" href="#управление-сессиями" aria-label="Permalink to &quot;Управление сессиями&quot;">​</a></h2><h3 id="просмотр-сессии" tabindex="-1">Просмотр сессий <a class="header-anchor" href="#просмотр-сессии" aria-label="Permalink to &quot;Просмотр сессий&quot;">​</a></h3><p>В приложении боковая панель сессий показывает все сессии выбранного Bot. Для каждой записи видны:</p><ul><li><strong>Title</strong> — название сессии (сгенерированное автоматически или заданное пользователем).</li><li><strong>Type</strong> — значок типа сессии.</li><li><strong>Last Activity</strong> — когда сессия была активна в последний раз.</li></ul><p>Для повседневной работы сессии <code>chat</code> и <code>discuss</code> намеренно показываются вместе: и те и другие — ветки диалога, обращённые к пользователю.</p><h3 id="переименование-сессии" tabindex="-1">Переименование сессий <a class="header-anchor" href="#переименование-сессии" aria-label="Permalink to &quot;Переименование сессий&quot;">​</a></h3><p>Щёлкните по названию сессии, чтобы переименовать её. Это помогает упорядочивать разговоры по темам.</p><h3 id="удаление-сессии" tabindex="-1">Удаление сессий <a class="header-anchor" href="#удаление-сессии" aria-label="Permalink to &quot;Удаление сессий&quot;">​</a></h3><p>Удаляйте сессии, которые больше не нужны. Удаление сессии безвозвратно стирает её историю сообщений.</p><hr><h2 id="панель-статуса-сессии" tabindex="-1">Панель статуса сессии <a class="header-anchor" href="#панель-статуса-сессии" aria-label="Permalink to &quot;Панель статуса сессии&quot;">​</a></h2><p>Панель статуса сессии даёт компактную сводку по активной сессии во время работы. Это та же информация, которую показывает <code>/status</code>.</p><p>Ключевые поля:</p><ul><li><strong>Messages</strong> — общее число сообщений в сессии</li><li><strong>Context Usage</strong> — занятые токены относительно <code>context_window</code> выбранной модели</li><li><strong>Cache Hit Rate</strong> — какая доля ввода пришла из чтений кэша</li><li><strong>Cache Read / Cache Write</strong> — счётчики токенов, связанные с кэшированием</li><li><strong>Skills</strong> — действующие навыки, использованные в сессии</li></ul><p>Панель также содержит кнопку <strong>Compact Now</strong>, которая немедленно запускает <a href="./compaction.html">сжатие контекста</a> для текущей сессии.</p><hr><h2 id="как-сессии-связаны-с-другими-функциями" tabindex="-1">Как сессии связаны с другими функциями <a class="header-anchor" href="#как-сессии-связаны-с-другими-функциями" aria-label="Permalink to &quot;Как сессии связаны с другими функциями&quot;">​</a></h2><ul><li>Сессии <strong>Discuss</strong> оптимизированы для каналов, где Bot должен наблюдать и говорить выборочно, особенно в групповых разговорах.</li><li>Сессии <strong>Schedule</strong> создаются при запуске задачи по расписанию. Загляните в них, чтобы увидеть результаты команд, запущенных по cron.</li><li>Сессии <strong>Subagent</strong> отслеживают делегированные задачи и показывают независимый рабочий контекст каждого вызова субагента. Субагенты получают почти полный набор инструментов родительского Bot — включая рабочее пространство, браузер, память и инструменты MCP, — но не могут напрямую писать пользователям, задавать пользователю вопросы или порождать новых субагентов. Делегируя, Bot может выбрать для каждого субагента свою модель чата и при желании ответвить (fork) в субагента текущий контекст разговора. Панель информации о сессии показывает активных в данный момент субагентов Bot.</li><li>Сессии <strong>ACP Agent</strong> отслеживают работу агентов для программирования, запущенную из чат-пространства через интеграцию Agents/ACP.</li><li><strong>Память</strong> общая для всех сессий Bot: воспоминания, извлечённые в одной сессии, доступны во всех остальных.</li></ul>',55)])])}const p=e(i,[["render",r]]);export{g as __pageData,p as default};
